definition.script:
var text = input.get('text') || '';
var maxTokens = parseInt(input.get('maxTokens') || '500');
var overlap = parseInt(input.get('overlap') || '50');
var customMetaJson = input.get('customMetadata') || '{}';
var sourceId = input.get('sourceId') || '';

if (!text) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Text input is required');
    tags.trigger('error');
} else {
    try {
        var customMeta = {};
        try { customMeta = json.parse(customMetaJson); } catch(e) {}

        var charsPerToken = 4;
        var maxChars = maxTokens * charsPerToken;
        var overlapChars = overlap * charsPerToken;

        var paragraphs = text.split(/\n\n+/);
        var chunks = [];
        var currentChunk = '';
        var currentTokens = 0;

        for (var i = 0; i < paragraphs.length; i++) {
            var para = paragraphs[i].trim();
            if (!para) continue;

            var paraTokens = Math.ceil(para.length / charsPerToken);

            if (currentTokens + paraTokens <= maxTokens) {
                currentChunk += (currentChunk ? '\n\n' : '') + para;
                currentTokens += paraTokens;
            } else {
                if (currentChunk) {
                    chunks.push(currentChunk);
                }

                if (paraTokens > maxTokens) {
                    var sentences = para.split(/(?<=[.!?])\s+/);
                    var sentenceChunk = '';
                    var sentenceTokens = 0;

                    for (var j = 0; j < sentences.length; j++) {
                        var sent = sentences[j].trim();
                        var sentTokens = Math.ceil(sent.length / charsPerToken);

                        if (sentenceTokens + sentTokens <= maxTokens) {
                            sentenceChunk += (sentenceChunk ? ' ' : '') + sent;
                            sentenceTokens += sentTokens;
                        } else {
                            if (sentenceChunk) chunks.push(sentenceChunk);
                            sentenceChunk = sent;
                            sentenceTokens = sentTokens;
                        }
                    }
                    if (sentenceChunk) {
                        currentChunk = sentenceChunk;
                        currentTokens = sentenceTokens;
                    } else {
                        currentChunk = '';
                        currentTokens = 0;
                    }
                } else {
                    currentChunk = para;
                    currentTokens = paraTokens;
                }
            }
        }

        if (currentChunk) {
            chunks.push(currentChunk);
        }

        var result = [];
        for (var k = 0; k < chunks.length; k++) {
            var chunkText = chunks[k];
            var wordCount = chunkText.split(/\s+/).length;
            var charCount = chunkText.length;
            var estTokens = Math.ceil(charCount / charsPerToken);

            var meta = {
                chunkIndex: k,
                totalChunks: chunks.length,
                charCount: charCount,
                wordCount: wordCount,
                estimatedTokens: estTokens
            };

            if (sourceId) meta.sourceId = sourceId;

            for (var key in customMeta) {
                if (customMeta.hasOwnProperty(key)) {
                    meta[key] = customMeta[key];
                }
            }

            result.push({
                text: chunkText,
                metadata: meta
            });
        }

        output.set('Chunks', json.stringify(result));
        output.set('ChunkCount', chunks.length);
        output.set('FirstChunk', chunks.length > 0 ? chunks[0] : '');
        output.set('FirstChunkMetadata', chunks.length > 0 ? json.stringify(result[0].metadata) : '{}');
        output.set('TotalCharacters', text.length);
        output.set('TotalWords', text.split(/\s+/).length);
        output.set('EstimatedTotalTokens', Math.ceil(text.length / charsPerToken));
        output.set('HasErrors', false);
        output.set('ErrorMessage', '');

        log.info('Chunked text into ' + chunks.length + ' chunks (max ' + maxTokens + ' tokens each)');
        tags.trigger('success');

    } catch (ex) {
        log.error('Chunking failed: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        tags.trigger('error');
    }
}
